\hat X(\vec r_2)=&\hat  X_c\otimes\hat  X_c\otimes\hat X_0\otimes\hat  X_b\otimes\ldots\otimes\hat  X_c\otimes\hat  X_c\\
&\ldots\\
\hat X(\vec r_{n-2})=&\hat  X_c\otimes\hat  X_c\otimes\hat X_c\otimes\hat  X_c\otimes\ldots\otimes\hat  X_0\otimes\hat  X_b\\
\hat X(\vec r_{n-1})=&\hat  X_b\otimes\hat  X_c\otimes\hat X_c\otimes\hat  X_c\otimes\ldots\otimes\hat  X_c\otimes\hat  X_0\\
\hat X(\vec 0)=&\hat  X_0\otimes\hat  X_0\otimes\hat X_0\otimes\hat  X_0\otimes\ldots\otimes\hat  X_0\otimes\hat  X_0\cr
